1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { requireAdmin } from "@/lib/auth";
5	import { db } from "@/lib/db";
6	import {
7	  isImprovementStatus,
8	  type ImprovementStatus,
9	  type BulkImprovementSelector,
10	} from "@/lib/improvement-status";
11	
12	/**
13	 * Owner-facing approve/decline actions for the Improvements board
14	 * (app/admin/improvements). Every action is ADMIN-guarded via requireAdmin().
15	 * NOTE: a "use server" module may ONLY export async functions — the status
16	 * constants and types live in lib/improvement-status.ts.
17	 */
18	
19	function assertStatus(status: string): asserts status is ImprovementStatus {
20	  if (!isImprovementStatus(status)) {
21	    throw new Error(`Invalid improvement status: ${status}`);
22	  }
23	}
24	
25	async function audit(userId: string | null, action: string, detail?: string) {
26	  try {
27	    await db.auditLog.create({ data: { userId, action, detail } });
28	  } catch {
29	    /* auditing is best-effort — never block the status change on it */
30	  }
31	}
32	
33	/** Set a single improvement's status. */
34	export async function setImprovementStatus(id: string, status: string): Promise<void> {
35	  const admin = await requireAdmin();
36	  assertStatus(status);
37	  await db.improvement.update({ where: { id }, data: { status } });
38	  await audit(admin.id, "improvement.status", `${id} → ${status}`);
39	  revalidatePath("/admin/improvements");
40	}
41	
42	/**
43	 * Bulk status change. Accepts either an explicit id list, a filter (category /
44	 * current status), or both. With no constraints at all it is a no-op guard —
45	 * we refuse an unbounded update so "Approve all" can never sweep the whole
46	 * table by accident.
47	 */
48	export async function bulkSetStatus(
49	  selector: BulkImprovementSelector,
50	  status: string
51	): Promise<{ count: number }> {
52	  const admin = await requireAdmin();
53	  assertStatus(status);
54	
55	  const where: {
56	    id?: { in: string[] };
57	    category?: string;
58	    status?: string;
59	  } = {};
60	  if (selector.ids && selector.ids.length > 0) where.id = { in: selector.ids };
61	  if (selector.category) where.category = selector.category;
62	  if (selector.onlyStatus) {
63	    assertStatus(selector.onlyStatus);
64	    where.status = selector.onlyStatus;
65	  }
66	
67	  // Refuse a truly unconstrained bulk update.
68	  if (Object.keys(where).length === 0) return { count: 0 };
69	
70	  const res = await db.improvement.updateMany({ where, data: { status } });
71	  await audit(
72	    admin.id,
73	    "improvement.bulkStatus",
74	    `${res.count} row(s) → ${status} (${JSON.stringify(selector)})`
75	  );
76	  revalidatePath("/admin/improvements");
77	  return { count: res.count };
78	}
