3	import { useMemo, useState, useTransition } from "react";
4	import { Badge } from "@/components/ui/primitives";
5	import { setImprovementStatus, bulkSetStatus } from "@/lib/actions-improvements";
6	import type { ImprovementStatus } from "@/lib/improvement-status";
7	
8	export type BoardItem = {
9	  id: string;
10	  category: string;
11	  severity: string;
12	  title: string;
13	  summary: string;
14	  detail: string | null;
15	  source: string | null;
16	  effort: string | null;
17	  filesHint: string | null;
18	  status: string;
19	  createdAt: string;
20	};
21	
22	const STATUS_TABS: { key: ImprovementStatus | "ALL"; label: string }[] = [
23	  { key: "PROPOSED", label: "Proposed" },
24	  { key: "APPROVED", label: "Approved" },
25	  { key: "IN_PROGRESS", label: "In progress" },
26	  { key: "DECLINED", label: "Declined" },
27	  { key: "DONE", label: "Done" },
28	  { key: "ALL", label: "All" },
29	];
30	
31	const SEVERITY_ORDER: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };
32	
33	function severityTone(sev: string): "red" | "amber" | "brand" | "slate" {
34	  if (sev === "critical") return "red";
35	  if (sev === "high") return "amber";
36	  if (sev === "medium") return "brand";
37	  return "slate";
38	}
39	
40	function cap(s: string): string {
41	  return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
42	}
43	
44	function Card({
45	  item,
46	  pending,
47	  onSet,
48	}: {
49	  item: BoardItem;
50	  pending: boolean;
51	  onSet: (id: string, status: ImprovementStatus) => void;
52	}) {
53	  const [open, setOpen] = useState(false);
54	  return (
55	    <div className="card p-4">
56	      <div className="flex items-start gap-3">
57	        <Badge tone={severityTone(item.severity)}>{item.severity}</Badge>
58	        <div className="min-w-0 flex-1">
59	          <p className="text-sm text-slate-300">
60	            <span className="font-semibold text-white">{item.title}</span>
61	            {" — "}
62	            {item.summary}
63	          </p>
64	          <div className="mt-2 flex flex-wrap items-center gap-2 text-[11px] text-slate-500">
65	            {item.effort && <Badge tone="slate">effort {item.effort}</Badge>}
66	            {item.source && <span>via {item.source}</span>}
67	            <span>· {new Date(item.createdAt).toLocaleDateString()}</span>
68	            {item.detail && (
69	              <button
70	                className="text-brand-300 hover:text-brand-200"
71	                onClick={() => setOpen((v) => !v)}
72	              >
73	                {open ? "Hide detail" : "Show detail"}
74	              </button>
75	            )}
76	          </div>
77	          {open && item.detail && (
78	            <div className="mt-3 space-y-2 rounded-lg border border-white/[0.06] bg-navy-950/50 p-3 text-[13px] leading-relaxed text-slate-300">
79	              <p className="whitespace-pre-wrap">{item.detail}</p>
80	              {item.filesHint && (
81	                <p className="text-xs text-slate-500">
82	                  Files: <span className="font-mono text-slate-400">{item.filesHint}</span>
83	                </p>
84	              )}
85	            </div>
86	          )}
87	        </div>
88	        <div className="flex shrink-0 flex-col items-end gap-1.5">
89	          {item.status !== "PROPOSED" && <Badge tone="slate">{item.status.toLowerCase().replace(/_/g, " ")}</Badge>}
90	          <div className="flex gap-1.5">
91	            {item.status !== "APPROVED" && (
92	              <button
93	                disabled={pending}
94	                onClick={() => onSet(item.id, "APPROVED")}
95	                className="rounded-lg border border-emerald-500/40 bg-emerald-500/10 px-2.5 py-1 text-xs font-semibold text-emerald-300 transition-colors hover:bg-emerald-500/20 disabled:opacity-50"
96	              >
97	                Approve
98	              </button>
99	            )}
100	            {item.status !== "DECLINED" && (
101	              <button
102	                disabled={pending}
103	                onClick={() => onSet(item.id, "DECLINED")}
104	                className="rounded-lg border border-red-500/40 bg-red-500/10 px-2.5 py-1 text-xs font-semibold text-red-300 transition-colors hover:bg-red-500/20 disabled:opacity-50"
105	              >
106	                Decline
107	              </button>
108	            )}
109	          </div>
110	        </div>
111	      </div>
112	    </div>
113	  );
114	}
115	
116	export function ImprovementsBoard({ items }: { items: BoardItem[] }) {
117	  const [tab, setTab] = useState<ImprovementStatus | "ALL">("PROPOSED");
118	  const [pending, startTransition] = useTransition();
119	
120	  const statusCounts = useMemo(() => {
121	    const c: Record<string, number> = {};
122	    for (const it of items) c[it.status] = (c[it.status] ?? 0) + 1;
123	    return c;
124	  }, [items]);
125	
126	  const filtered = useMemo(
127	    () => (tab === "ALL" ? items : items.filter((it) => it.status === tab)),
128	    [items, tab]
129	  );
130	
131	  // Group by category, each group's cards sorted by severity (critical → low).
132	  const groups = useMemo(() => {
133	    const map = new Map<string, BoardItem[]>();
134	    for (const it of filtered) {
135	      const arr = map.get(it.category) ?? [];
136	      arr.push(it);
137	      map.set(it.category, arr);
138	    }
139	    return [...map.entries()]
140	      .map(([category, rows]) => ({
141	        category,
142	        rows: rows.sort(
143	          (a, b) => (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9)
144	        ),
145	      }))
146	      .sort((a, b) => a.category.localeCompare(b.category));
147	  }, [filtered]);
148	
149	  const set = (id: string, status: ImprovementStatus) =>
150	    startTransition(() => setImprovementStatus(id, status));
151	
152	  const approveGroup = (category: string) =>
153	    startTransition(() =>
154	      bulkSetStatus({ category, onlyStatus: "PROPOSED" }, "APPROVED").then(() => undefined)
155	    );
156	
157	  const approveAll = () =>
158	    startTransition(() =>
159	      bulkSetStatus({ onlyStatus: "PROPOSED" }, "APPROVED").then(() => undefined)
160	    );
161	
162	  const proposedShown = filtered.some((it) => it.status === "PROPOSED");
163	
164	  return (
165	    <div className="space-y-6">
166	      {/* Status filter tabs */}
167	      <div className="flex flex-wrap items-center gap-1.5 border-b border-white/[0.06] pb-3">
168	        {STATUS_TABS.map((t) => {
169	          const n = t.key === "ALL" ? items.length : statusCounts[t.key] ?? 0;
170	          const active = tab === t.key;
171	          return (
172	            <button
173	              key={t.key}
174	              onClick={() => setTab(t.key)}
175	              className={`rounded-full px-3.5 py-1.5 text-[13px] font-medium transition-colors ${
176	                active
177	                  ? "bg-brand-500/15 text-brand-200 ring-1 ring-inset ring-brand-500/40"
178	                  : "text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"
179	              }`}
180	            >
181	              {t.label}
182	              <span className="ml-1.5 text-slate-500">{n}</span>
183	            </button>
184	          );
185	        })}
186	        {tab === "PROPOSED" && proposedShown && (
187	          <button
188	            disabled={pending}
189	            onClick={approveAll}
190	            className="ml-auto rounded-lg border border-emerald-500/40 bg-emerald-500/10 px-3 py-1.5 text-xs font-semibold text-emerald-300 transition-colors hover:bg-emerald-500/20 disabled:opacity-50"
191	          >
192	            Approve all proposed
193	          </button>
194	        )}
195	      </div>
196	
197	      {/* Per-category count chips for the active filter */}
198	      {groups.length > 0 && (
199	        <div className="flex flex-wrap gap-2">
200	          {groups.map((g) => (
201	            <span
202	              key={g.category}
203	              className="inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-white/[0.04] px-3 py-1 text-xs text-slate-300"
204	            >
205	              {cap(g.category)}
206	              <span className="font-semibold text-white">{g.rows.length}</span>
207	            </span>
208	          ))}
209	        </div>
210	      )}
211	
212	      {groups.length === 0 ? (
213	        <div className="card py-12 text-center text-sm text-slate-400">
214	          Nothing here — no improvements with this status.
215	        </div>
216	      ) : (
217	        groups.map((g) => (
218	          <section key={g.category} className="space-y-3">
219	            <div className="flex items-center justify-between">
220	              <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-400">
221	                {cap(g.category)}
222	                <span className="ml-2 text-slate-600">{g.rows.length}</span>
223	              </h2>
224	              {tab === "PROPOSED" && g.rows.some((r) => r.status === "PROPOSED") && (
225	                <button
226	                  disabled={pending}
227	                  onClick={() => approveGroup(g.category)}
228	                  className="rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-2.5 py-1 text-xs font-medium text-emerald-300 transition-colors hover:bg-emerald-500/15 disabled:opacity-50"
229	                >
230	                  Approve all {cap(g.category)}
231	                </button>
232	              )}
233	            </div>
234	            <div className="space-y-2.5">
235	              {g.rows.map((it) => (
236	                <Card key={it.id} item={it} pending={pending} onSet={set} />
237	              ))}
238	            </div>
239	          </section>
240	        ))
241	      )}
242	    </div>
243	  );
244	}
