function Card({
  item,
  pending,
  onSet,
  onSaveNote,
}: {
  item: BoardItem;
  pending: boolean;
  onSet: (id: string, status: ImprovementStatus) => void;
  onSaveNote: (id: string, note: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const [noteOpen, setNoteOpen] = useState(false);
  const [noteDraft, setNoteDraft] = useState(item.ownerNote ?? "");
  const hasNote = !!(item.ownerNote && item.ownerNote.trim().length > 0);
  return (
    <div className="card p-4">
      <div className="flex items-start gap-3">
        <Badge tone={severityTone(item.severity)}>{item.severity}</Badge>
        <div className="min-w-0 flex-1">
          <p className="text-sm text-slate-300">
            <span className="font-semibold text-white">{item.title}</span>
            {" — "}
            {item.summary}
          </p>
          <div className="mt-2 flex flex-wrap items-center gap-2 text-[11px] text-slate-500">
            {item.effort && <Badge tone="slate">effort {item.effort}</Badge>}
            {item.source && <span>via {item.source}</span>}
            <span>· {new Date(item.createdAt).toLocaleDateString()}</span>
            {item.detail && (
              <button
                className="text-brand-300 hover:text-brand-200"
                onClick={() => setOpen((v) => !v)}
              >
                {open ? "Hide detail" : "Show detail"}
              </button>
            )}
            <button
              className={`transition-colors ${
                noteOpen
                  ? "text-brand-200"
                  : hasNote
                    ? "text-amber-300 hover:text-amber-200"
                    : "text-slate-500 hover:text-slate-300"
              }`}
              onClick={() => {
                setNoteDraft(item.ownerNote ?? "");
                setNoteOpen((v) => !v);
              }}
            >
              {noteOpen ? "Hide note" : hasNote ? "★ Note" : "Add note"}
            </button>
          </div>
          {open && item.detail && (
            <div className="mt-3 space-y-2 rounded-lg border border-white/[0.06] bg-navy-950/50 p-3 text-[13px] leading-relaxed text-slate-300">
              <p className="whitespace-pre-wrap">{item.detail}</p>
              {item.filesHint && (
                <p className="text-xs text-slate-500">
                  Files: <span className="font-mono text-slate-400">{item.filesHint}</span>
                </p>
              )}
            </div>
          )}
          {!noteOpen && hasNote && (
            <div className="mt-3 rounded-lg border border-amber-500/20 bg-amber-500/[0.06] p-3 text-[13px] leading-relaxed text-amber-100/90">
              <p className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-amber-300/80">
                Owner note
              </p>
              <p className="whitespace-pre-wrap">{item.ownerNote}</p>
            </div>
          )}
          {noteOpen && (
            <div className="mt-3 space-y-2 rounded-lg border border-white/[0.06] bg-navy-950/50 p-3">
              <label className="block text-[10px] font-semibold uppercase tracking-wide text-slate-400">
                Owner note — instructions for how to handle this
              </label>
              <textarea
                value={noteDraft}
                onChange={(e) => setNoteDraft(e.target.value)}
                maxLength={4000}
                rows={3}
                placeholder="e.g. Only do this for the EU region; coordinate with billing first…"
                className="w-full resize-y rounded-lg border border-white/10 bg-navy-950/60 px-3 py-2 text-[13px] text-slate-200 placeholder:text-slate-600 focus:border-brand-500/50 focus:outline-none focus:ring-1 focus:ring-brand-500/40"
              />
              <div className="flex items-center justify-end gap-2">
                <button
                  disabled={pending}
                  onClick={() => {
                    setNoteDraft(item.ownerNote ?? "");
                    setNoteOpen(false);
                  }}
                  className="rounded-lg px-2.5 py-1 text-xs font-medium text-slate-400 transition-colors hover:text-slate-200 disabled:opacity-50"
                >
                  Cancel
                </button>
                <button
                  disabled={pending || noteDraft === (item.ownerNote ?? "")}
                  onClick={() => {
                    onSaveNote(item.id, noteDraft);
                    setNoteOpen(false);
                  }}
                  className="rounded-lg border border-brand-500/40 bg-brand-500/10 px-2.5 py-1 text-xs font-semibold text-brand-200 transition-colors hover:bg-brand-500/20 disabled:opacity-50"
                >
                  Save note
                </button>
              </div>
            </div>
          )}
        </div>

const set = (id: string, status: ImprovementStatus) =>
  startTransition(() => setImprovementStatus(id, status));

const saveNote = (id: string, note: string) =>
  startTransition(() => setImprovementNote(id, note));
